css:
@media (max-width: 880px) {
  .mm-l5__top { font-size: 10px; padding: 6px 14px; letter-spacing: 0.12em; }
}

@media (max-width: 880px) {
  .mm-l5__top span:last-child { display: none; }
}

@media (max-width: 1100px) {
  .mm-l5__inner { gap: 10px; padding: 0px 16px; }
}

@media (max-width: 880px) {
  .mm-l5__inner { grid-template-columns: auto 1fr auto; padding: 0px 14px; }
}

@media (max-width: 1100px) {
  .mm-l5__logo { width: 170px; height: 62px; }
}

@media (max-width: 880px) {
  .mm-l5__logo { width: 140px; height: 52px; }
}

@media (max-width: 880px) {
  .mm-l5__nav { display: none; }
}

@media (max-width: 1100px) {
  .mm-l5__nav a { padding: 22px 14px; font-size: 13px; }
}

@media (max-width: 1100px) {
  .mm-l5__members, .mm-l5__account { font-size: 11px; padding: 8px 12px; letter-spacing: 0.1em; }
}

@media (max-width: 1100px) {
  html body:not(.elementor-editor-active):not(.mm-l5-on)::before { height: 92px; }
}

@media (max-width: 880px) {
  html body:not(.elementor-editor-active):not(.mm-l5-on)::before { height: 78px; }
}

@media (max-width: 1100px) {
  .mm-l5__inner { gap: 10px; padding: 0px 16px; }
  .mm-l5__nav a { padding: 22px 14px; font-size: 13px; }
  .mm-l5__members, .mm-l5__account { font-size: 11px; padding: 8px 12px; letter-spacing: 0.1em; }
  .mm-l5__logo { width: 170px; height: 62px; }
}

@media (max-width: 880px) {
  .mm-l5__top { font-size: 10px; padding: 6px 14px; letter-spacing: 0.12em; }
  .mm-l5__top span:last-child { display: none; }
  .mm-l5__nav { display: none; }
  .mm-l5__inner { grid-template-columns: auto 1fr auto; padding: 0px 14px; }
  .mm-l5__logo { width: 140px; height: 52px; }
}
